insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'r_arancel', 'EE.UU. impone un arancel de 12,5% a Costa Rica por presunto trabajo forzoso en la cadena de suministro', true, 'Economía y comercio', 'La República (CR)', 'https://www.larepublica.net/noticia/ee-uu-cobrara-125-de-aranceles-a-exportaciones-ticas', '2026-07-23'::date, 'Es real. Ocurrió el 24 de julio de 2026.', 'La reportaron agencias internacionales y medios nacionales en julio de 2026.', array[]::text[], '{"who":"Tío Fernando","many":true,"band":"URGENTE","bg":"linear-gradient(135deg,#1F3B73,#B22234)","emo":"📦","emo2":"⛓️","src_label":"Fuente citada: AP / medios internacionales"}'::jsonb, 'requiere_precision', 'El arancel (de 10% a 12,5%, vigente 24/07/2026) se vincula a investigaciones de USTR sobre la falta de aplicación de una prohibición de importar bienes hechos con trabajo forzoso (60 economías), no a trabajo forzoso comprobado en la cadena costarricense; Infobae indica que aplica a ''parte de las exportaciones''. El titular simplifica. La fuente citada en la tarjeta (AP) no se localizó; se documenta La República, Infobae (25/07/2026) y Delfino. Fuentes adicionales: https://www.infobae.com/costa-rica/2026/07/25/eeuu-eleva-a-125-el-arancel-para-parte-de-las-exportaciones-de-costa-rica-por-cuestionamientos-sobre-trabajo-forzado/'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;
insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'f_marihuana', 'Desde noviembre será legal comprar marihuana recreativa en farmacias de Costa Rica', false, 'Política nacional', null, null, null, 'Es inventada para este juego.', 'Ningún medio la reporta y un cambio de ley así pasaría por la Asamblea con mucha cobertura.', array['No dice quién lo anunció ni cita ninguna ley.','Un cambio de ley así sería noticia en todos los medios.','Toca un tema polémico para que reacciones rápido.']::text[], '{"who":"Grupo U 🎓","many":false,"band":"NACIONAL","bg":"linear-gradient(135deg,#2F7D32,#A5D6A7)","emo":"🌿","emo2":"💊","src_label":"Sin fuente"}'::jsonb, 'requiere_correccion', 'La afirmación específica (venta legal en farmacias desde noviembre) es falsa. Pero existe un proyecto de ley del Gobierno sobre marihuana recreativa con cobertura mediática (p. ej. https://observador.cr/gobierno-enviara-proyecto-de-ley-para-legalizar-la-marihuana-recreativa-en-costa-rica/), por lo que la pista ''Ningún medio la reporta'' es imprecisa: sugerir ''Hay un proyecto en discusión, pero no es ley ni autoriza venta en farmacias''.'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;
insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'r_cuba', 'Costa Rica rompe relaciones diplomáticas con Cuba y ordena cerrar su embajada', true, 'Política internacional', 'ADN40 / Reuters (18/03/2026)', 'https://www.adn40.mx/internacional/2026-03-18/costa-rica-cierra-su-embajada-en-cuba-la-habana-apunta-a-presiones-trump', '2026-03-18'::date, 'Es real. Sucedió el 18 de marzo de 2026.', 'Se publicó en medios nacionales e internacionales en marzo de 2026.', array[]::text[], '{"who":"Mamá","many":false,"band":"INTERNACIONAL","bg":"linear-gradient(135deg,#0B3D91,#CF142B)","emo":"🏛️","emo2":"✂️","src_label":"Fuente citada: CBS News"}'::jsonb, 'requiere_precision', 'El 17-18/03/2026 Costa Rica cerró su embajada y pidió la salida del personal diplomático cubano. Según Cuba (Tico Times, 20/09/2026), la nota de marzo no declaró una ruptura formal; el canciller confirmó la ruptura el 19/09/2026. ''Rompe relaciones'' en marzo es discutible. No se localizó la nota de CBS News citada. Ver https://ticotimes.net/2026/09/20/costa-rica-cuba-diplomatic-relations-break'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;
insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'f_ingles', 'Por el recorte de presupuesto, el MEP eliminará las clases de inglés en primaria a partir de 2027', false, 'Educación', null, null, null, 'Es inventada para este juego, pero se monta sobre una noticia real: el recorte al presupuesto de educación.', 'El recorte sí es real, pero no hay ningún anuncio sobre eliminar el inglés.', array['Mezcla un hecho real con uno falso: es la técnica más efectiva.','No cita comunicado del MEP.','Busca indignación.']::text[], '{"who":"Profe Andrea","many":true,"band":"EDUCACIÓN","bg":"linear-gradient(135deg,#F2994A,#F2C94C)","emo":"📚","emo2":"🚫","src_label":"Sin fuente"}'::jsonb, 'ficticia_documentada', 'No se encontró anuncio del MEP sobre eliminar inglés en primaria (búsqueda 09/10/2026). El recorte presupuestario de referencia es real (ver r_recorte).'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;
