select id, 'r_hermano', 'Hermano de un ministro obtuvo una mejora salarial de ₡2 millones gracias a un puesto en el Gobierno', true, 'Función pública', 'CR Hoy (03/10/2026)', 'https://crhoy.com/nacionales/hermano-de-ministro-tuvo-mejora-salarial-de-₡2-millones-gracias-a-puesto-en-el-gobierno/', '2026-10-03'::date, 'Es real. CR Hoy lo publicó en octubre de 2026.', 'Lo publicó CR Hoy a inicios de octubre de 2026.', array[]::text[], '{"who":"Don Rigo","many":true,"band":"ESCÁNDALO","bg":"linear-gradient(135deg,#3E2723,#8D6E63)","emo":"💰","emo2":"🏛️","src_label":"Fuente citada: CR Hoy"}'::jsonb, 'verificada', 'CR Hoy, 03/10/2026: pasó de ₡2,1 millones (fiscal) a ₡4,2 millones (asesor en el ICE). Es un reportaje periodístico, no una resolución oficial.'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;
