select id, 'f_ejercito', 'URGENTE: la Asamblea Legislativa aprobó en primer debate volver a crear el ejército', false, 'Política nacional', null, null, null, 'Es inventada para este juego.', 'Abolir el ejército está en la Constitución; cambiarlo sería un hecho histórico con cobertura mundial.', array['Mayúsculas y "URGENTE" para generar alarma.','Sería una reforma constitucional: imposible que pase en silencio.','No hay votación registrada ni medio que lo publique.']::text[], '{"who":"Tío Fernando","many":true,"band":"URGENTE","bg":"linear-gradient(135deg,#33691E,#827717)","emo":"🪖","emo2":"🇨🇷","src_label":"Sin fuente"}'::jsonb, 'ficticia_documentada', 'Artículo 12 de la Constitución Política proscribe el ejército como institución permanente. No hay registro de tal votación.'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;
insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'r_bus', 'El pasaje de una ruta de bus en Alajuela pasó de ₡260 a ₡1.000', true, 'Transporte y costo de vida', 'La Teja (07/10/2026)', 'https://www.lateja.cr/finanzas-y-tecnologia/bus-de-ruta-de-alajuela-amanecio-este-miercoles/PYIMWBYERVCPJMHNVS4ZA3DRWA/story/', '2026-10-07'::date, 'Es real. La Teja lo publicó el 2 de octubre de 2026.', 'Lo publicó La Teja el 2 de octubre de 2026.', array[]::text[], '{"who":"Vecina Lucía","many":true,"band":"INDIGNANTE","bg":"linear-gradient(135deg,#00695C,#4DB6AC)","emo":"🚌","emo2":"💸","src_label":"Fuente citada: La Teja"}'::jsonb, 'requiere_precision', 'Ruta 220 Alajuela–barrio San José. La solicitud se publicó en julio (CR Hoy) y ARESEP la aprobó a inicios de octubre; La Teja informó el cobro vigente el 07/10/2026. No se confirmó la fecha ''2 de octubre'' que mencionan la pista y la explicación.'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
