insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'r_recorte', 'Gremios rechazan recorte de ₡19 mil millones a educación: alertan que afectaría becas y comedores escolares', true, 'Educación', 'Diario Extra', 'https://www.diarioextra.com/videos/ecorte-presupuesto-educativo-costa-rica/', '2026-09-04'::date, 'Es real. Diario Extra lo publicó el 4 de septiembre de 2026.', 'Lo publicó Diario Extra el 4 de septiembre de 2026.', array[]::text[], '{"who":"Profe Andrea","many":false,"band":"PRESUPUESTO","bg":"linear-gradient(135deg,#4A148C,#9575CD)","emo":"✂️","emo2":"🍽️","src_label":"Fuente citada: Diario Extra"}'::jsonb, 'verificada', 'SIDE, SEC y APSE rechazan ~₡19 mil millones menos para el MEP en el presupuesto 2027; mencionan becas y comedores. La página muestra fechas contradictorias (metadatos 04/09/2026, texto 08/10/2026).'
