insert into public.news_items (study_id, item_key, headline, is_real, category, source_name, source_url, source_published_on, explanation, hint, red_flags, display, validation_status, validation_notes)
select id, 'f_sinpe', 'A partir del 1 de noviembre SINPE Móvil cobrará ₡150 por cada transferencia. ¡Avísale a todos!', false, 'Finanzas personales', null, null, null, 'Es inventada para este juego.', 'El Banco Central no ha anunciado ningún cobro así.', array['Pide reenviarlo a todos.','Fecha cercana para que reacciones sin pensar.','Ningún enlace ni comunicado oficial.']::text[], '{"who":"Tía Marielos","many":true,"band":"⚠️ ATENCIÓN","bg":"linear-gradient(135deg,#C62828,#FF8A65)","emo":"📱","emo2":"💳","src_label":"Sin fuente"}'::jsonb, 'requiere_correccion', 'No existe un cobro fijo de ₡150 por transferencia. Sin embargo, desde octubre de 2025 varios bancos cobran comisión al superar montos diarios (CR Hoy, 16/10/2025: https://www.crhoy.com/varios-bancos-ya-estan-aplicando-cambios-en-sinpe-movil-enterese-aqui-cuales-son/). Participantes informados podrían considerarla plausible; la pista debería decir ''No hay un cobro fijo por cada transferencia; solo algunos bancos cobran por encima de ciertos montos diarios''.'
from public.studies where code = 'lo-reenviarias' and version = '1.0.0'
on conflict (study_id, item_key) do nothing;

insert into public.studies (code, version, title, description, status, config, changelog)
values ('lo-reenviarias', '2.0.0', '¿Lo reenviarías? — plataforma 2.0', 'Mismas 10 noticias, mismas preguntas, misma regla de puntuación. Cambios técnicos: puntuación calculada en servidor, orden aleatorio en servidor, temporizador siempre activo, guardado incremental con reintentos.', 'active', '{"items_per_session":10,"seconds_per_item":20,"hints_per_session":2,"show_crowd_feedback":false,"min_crowd_n":3,"timer_runs_with_reduced_motion":true,"max_sessions_per_minute":120,"public_stats_min_n":10,"percentile_min_n":20}'::jsonb, 'Técnico: puntuación/aciertos en servidor; respuestas correctas solo tras cada decisión; guardado por decisión; temporizador independiente de animaciones. Metodológico (registrado): se desactiva por defecto el porcentaje de la multitud durante el juego (influencia social); se añade aceptación informada explícita al iniciar.')
on conflict (code, version) do nothing;
